-- Seed data for tickets table. Fields match app.models.ticket.Ticket.
ON DUPLICATE KEY UPDATE user_id=VALUES(user_id), order_no=VALUES(order_no), session_id=VALUES(session_id), issue_type=VALUES(issue_type), title=VALUES(title), description=VALUES(description), priority=VALUES(priority), status=VALUES(status), source=VALUES(source), trace_id=VALUES(trace_id);